request.user_message:
Compare the typed predicate candidates against the existing registry.
Candidate predicates:
[
  {
    "name": "INTERPRETS_OBSERVATION_AS_NONCOMPLIANT_PROPERTY",
    "definition": "The reasoning treats a concrete artifact property visible in an observation as evidence that the artifact may violate a formatting, structural, or other acceptance requirement.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node that evaluates the observed artifact property."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation displaying the artifact property that is judged noncompliant or risky."
      }
    ],
    "assertion_conditions": [
      "The observation displays or reports a concrete artifact property.",
      "The reasoning explicitly connects that observed property to a possible compliance failure and treats it as grounds for corrective action."
    ],
    "exclusion_conditions": [
      "The reasoning merely restates or describes the observation without judging compliance.",
      "The observation does not contain the property in question.",
      "The reasoning interprets the observation as confirming compliance or as unrelated to acceptance."
    ]
  },
  {
    "name": "CHOOSES_PREEMPTIVE_REMEDIATION",
    "definition": "The reasoning decides to modify an artifact proactively to eliminate a possible specification-compliance failure, even though the artifact may already be acceptable under normal handling.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node that identifies the risk and selects the proactive correction."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies a potential compliance failure and indicates that the artifact may otherwise be acceptable under normal handling.",
      "The reasoning selects a corrective modification to guarantee strict compliance before finalizing."
    ],
    "exclusion_conditions": [
      "The reasoning responds only to a confirmed failure that must be fixed.",
      "The reasoning identifies a risk but does not decide to modify the artifact.",
      "The reasoning decides to leave the artifact unchanged or only notes the risk."
    ]
  },
  {
    "name": "IMPLEMENTS_INTENDED_CORRECTION",
    "definition": "The action performs a modification that the reasoning explicitly intended in order to remove or reduce an identified defect or compliance risk in an artifact or state.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node that states the intended corrective change."
      },
      {
        "name": "corrective_action",
        "type": "action",
        "description": "The action that carries out the intended modification."
      }
    ],
    "assertion_conditions": [
      "The reasoning states a specific corrective change to be made.",
      "The action performs that change on the same artifact or state.",
      "The action modifies the artifact rather than merely inspecting it."
    ],
    "exclusion_conditions": [
      "The reasoning only plans verification, exploration, or a generic next step.",
      "The action reads, lists, or inspects the artifact without changing it.",
      "The action changes a different property or artifact than the one identified in the reasoning."
    ]
  },
  {
    "name": "VERIFIES_CORRECTION_OUTCOME",
    "definition": "A corrective modification is followed by a targeted inspection whose observation provides evidence that the defect or compliance risk addressed by the modification has been eliminated.",
    "parameters": [
      {
        "name": "corrective_action",
        "type": "action",
        "description": "The action that applied the corrective modification."
      },
      {
        "name": "verification_action",
        "type": "action",
        "description": "The later action that inspects the artifact property affected by the correction."
      },
      {
        "name": "verification_observation",
        "type": "observation",
        "description": "The observation reporting whether the corrected property now holds."
      }
    ],
    "assertion_conditions": [
      "The corrective action modifies an artifact to address an identified defect or compliance risk.",
      "A subsequent verification action inspects the relevant property of the same artifact.",
      "The observation reports that the corrected property holds or that the defect is absent."
    ],
    "exclusion_conditions": [
      "The verification action inspects an unrelated property or artifact.",
      "The observation does not show removal of the defect or is ambiguous about it.",
      "No corrective modification occurred."
    ]
  },
  {
    "name": "VERIFIES_ARTIFACT_PROPERTY_WITH_PROBE",
    "definition": "A targeted inspection action obtains direct evidence about a specified property of an artifact, and the resulting observation reports whether that property holds.",
    "parameters": [
      {
        "name": "verification_reasoning",
        "type": "reasoning",
        "description": "The reasoning node that specifies the artifact property or requirement to verify."
      },
      {
        "name": "probe_action",
        "type": "action",
        "description": "The targeted inspection action that examines the artifact."
      },
      {
        "name": "probe_observation",
        "type": "observation",
        "description": "The observation reporting evidence about the specified property."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies one or more checkable properties or requirements of an artifact to be verified.",
      "The action inspects the artifact's actual representation in a way relevant to those properties.",
      "The observation reports evidence that directly confirms or refutes the specified property."
    ],
    "exclusion_conditions": [
      "No explicit artifact property or requirement is being verified.",
      "The action modifies the artifact instead of inspecting it, or inspects unrelated content.",
      "The observation does not report the property or cannot resolve whether it holds."
    ]
  },
  {
    "name": "CONFIRMS_EXPECTED_ARTIFACT_PROPERTY",
    "definition": "The reasoning treats an observation as confirming that an artifact satisfies a property or requirement that was expected or being checked.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node that acknowledges or relies on the confirmed property."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation containing evidence that the expected property holds."
      }
    ],
    "assertion_conditions": [
      "The reasoning states or implies an expected or required artifact property.",
      "The observation contains direct evidence that the artifact has that property.",
      "The reasoning acknowledges or relies on the property as holding."
    ],
    "exclusion_conditions": [
      "The observation reveals a mismatch or is ambiguous about the property.",
      "The reasoning does not connect the observation to the expected property.",
      "The observation only establishes artifact existence or reports unrelated content."
    ]
  },
  {
    "name": "ASSERTS_TASK_COMPLETION",
    "definition": "The reasoning makes a final claim that the task's required deliverable and acceptance conditions have been satisfied.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node containing the final completion claim."
      }
    ],
    "assertion_conditions": [
      "The reasoning explicitly declares the task complete, done, or finally achieved.",
      "The claim refers to the required deliverable or to acceptance conditions being met.",
      "The statement is a conclusion about final state rather than merely a plan or intermediate progress report."
    ],
    "exclusion_conditions": [
      "The reasoning only describes intended future work or partial progress.",
      "The reasoning expresses unresolved uncertainty about whether requirements are met.",
      "The reasoning reports a completed subtask without claiming overall completion."
    ]
  },
  {
    "name": "GROUNDS_COMPLETION_CLAIM_IN_VERIFICATION_OBSERVATION",
    "definition": "A final completion claim is explicitly supported by observation evidence that the deliverable was inspected and satisfies the relevant requirements.",
    "parameters": [
      {
        "name": "completion_reasoning",
        "type": "reasoning",
        "description": "The reasoning node that asserts task or deliverable completion."
      },
      {
        "name": "verification_observation",
        "type": "observation",
        "description": "The observation reporting validation evidence for the final deliverable."
      }
    ],
    "assertion_conditions": [
      "The reasoning asserts that the task or deliverable is complete.",
      "The reasoning cites or directly relies on the observation as evidence of validation.",
      "The observation reports a check of the final artifact's properties or contents relevant to acceptance."
    ],
    "exclusion_conditions": [
      "The completion claim is not connected to the observation.",
      "The observation only shows that a file exists or reports unrelated information.",
      "The reasoning only plans verification rather than claiming completion."
    ]
  }
]

Existing registry:
[
  {
    "name": "IS_PLAN",
    "definition": "The reasoning explicitly expresses at least one intended future action or sequence of actions to be taken in service of the task.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text expressing an intended future action or plan."
      }
    ],
    "assertion_conditions": [
      "The reasoning explicitly identifies at least one operation or sequence of operations that the agent intends to perform later.",
      "The intended action is presented as something to be done, not merely as a completed observation or factual statement."
    ],
    "exclusion_conditions": [
      "The reasoning only reports actions that have already been completed.",
      "The reasoning states a fact or diagnosis without expressing any intended future action.",
      "The reasoning only restates the task requirements without committing to any operation the agent will itself carry out."
    ]
  },
  {
    "name": "ACTION_IMPLEMENTS_PLANNED_STEP",
    "definition": "A recorded action carries out an operation that a reasoning node explicitly proposed as a future step, with matching task purpose rather than merely topical or temporal adjacency.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The recorded tool invocation that performs the step."
      },
      {
        "name": "plan_reasoning",
        "type": "reasoning",
        "description": "The reasoning node that proposes the future operation."
      }
    ],
    "assertion_conditions": [
      "The plan_reasoning expresses an intended future operation or set of operations.",
      "The action performs an operation consistent with the purpose and target of the proposed step."
    ],
    "exclusion_conditions": [
      "The reasoning only describes past or completed actions.",
      "The action is unrelated to the proposed step or serves a different purpose.",
      "The connection is based only on temporal adjacency without matching intent."
    ]
  },
  {
    "name": "DIAGNOSES_OBSERVED_ARTIFACT_DEFECT",
    "definition": "The reasoning interprets content of an artifact exposed in an observation and identifies a specific missing, incomplete, or erroneous element that must be repaired.",
    "parameters": [
      {
        "name": "diagnosis_reasoning",
        "type": "reasoning",
        "description": "The reasoning that identifies the artifact defect or incompleteness."
      },
      {
        "name": "artifact_observation",
        "type": "observation",
        "description": "The observation exposing the artifact content being diagnosed."
      }
    ],
    "assertion_conditions": [
      "The observation exposes identifiable content of an artifact.",
      "The reasoning identifies a specific defect, gap, or incomplete element in that artifact relative to the intended requirement."
    ],
    "exclusion_conditions": [
      "The reasoning merely repeats or paraphrases the artifact content without identifying a defect.",
      "No specific missing, incomplete, or erroneous element is identified.",
      "The observation does not expose artifact content relevant to the diagnosis."
    ]
  },
  {
    "name": "PROPOSES_CONCRETE_REMEDIATION",
    "definition": "The reasoning specifies a concrete correction, completion, or remediation for an identified defect, gap, or requirement, including replacement content or steps intended to make the target satisfy the requirement.",
    "parameters": [
      {
        "name": "remediation_reasoning",
        "type": "reasoning",
        "description": "The reasoning containing the proposed concrete remediation or completion."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies at least one concrete change, replacement, or added step intended to repair, complete, or remedy an identified defect, gap, or unmet requirement.",
      "The proposed remediation is tied to an identified defect, gap, or requirement rather than being a generic intention to fix something."
    ],
    "exclusion_conditions": [
      "The reasoning only identifies a defect without proposing how to repair or complete it.",
      "The reasoning expresses only a generic intention to fix or improve without concrete content or steps.",
      "The proposed change is unrelated to the identified defect or requirement."
    ]
  },
  {
    "name": "PROBES_CAPABILITY_AVAILABILITY",
    "definition": "An action probes the execution environment for the availability, identity, or version of a capability or resource required for the task, and its observation reports capability evidence.",
    "parameters": [
      {
        "name": "probe_action",
        "type": "action",
        "description": "The diagnostic action that queries the environment for capability or resource availability."
      },
      {
        "name": "probe_observation",
        "type": "observation",
        "description": "The observation reporting the presence, absence, availability, identity, or version of the queried capability or resource."
      }
    ],
    "assertion_conditions": [
      "The action is a diagnostic query about a capability or resource relevant to the task.",
      "The observation reports capability evidence such as presence, absence, availability, identity, or version of the queried capability or resource."
    ],
    "exclusion_conditions": [
      "The action performs the primary task rather than checking capability or resource availability.",
      "The observation does not report any information about capability availability, identity, or version.",
      "The probe is unrelated to a capability or resource required by the task."
    ]
  },
  {
    "name": "IMPLEMENTS_SPECIFIED_CHANGE",
    "definition": "An action applies concrete content, settings, or corrections that a reasoning node specified as intended, writing or applying them to the relevant target, and the observation reports that the application succeeded.",
    "parameters": [
      {
        "name": "change_action",
        "type": "action",
        "description": "The action that writes or applies the specified content, settings, or correction."
      },
      {
        "name": "change_reasoning",
        "type": "reasoning",
        "description": "The reasoning specifying the intended content, settings, target change, or correction."
      },
      {
        "name": "application_observation",
        "type": "observation",
        "description": "The observation reporting whether the specified change was successfully applied."
      }
    ],
    "assertion_conditions": [
      "The reasoning specifies intended content, settings, a target change, or a correction to be put in place.",
      "The action applies content or changes corresponding to that stated intent to the relevant target.",
      "The observation reports successful creation, writing, modification, or application of that change."
    ],
    "exclusion_conditions": [
      "The action does not implement the content or change described in the reasoning.",
      "The observation reports failure, an error, or only an attempt without confirming the write or application.",
      "The reasoning only discusses a change without stating an intended specification or correction."
    ]
  },
  {
    "name": "PRODUCES_EXPECTED_DERIVED_OUTPUT",
    "definition": "An action invokes a transformation, build, compilation, or generation step on a source input, and its observation provides evidence that the expected derived artifact or output was generated.",
    "parameters": [
      {
        "name": "transformation_action",
        "type": "action",
        "description": "The action that runs the transformation, build, compilation, or generation process."
      },
      {
        "name": "generation_observation",
        "type": "observation",
        "description": "The observation reporting generation or existence of the expected derived output."
      }
    ],
    "assertion_conditions": [
      "The action invokes a transformation, build, compilation, or equivalent generation step on a source input.",
      "The observation provides evidence that the expected derived artifact or output was produced or exists after the step."
    ],
    "exclusion_conditions": [
      "The action only inspects files or inputs without invoking a transformation or generation step.",
      "The observation does not show that the expected derived artifact or output was generated.",
      "The transformation or generation reports an error preventing output production."
    ]
  },
  {
    "name": "DIAGNOSES_ACTION_FAILURE_FROM_ERROR",
    "definition": "The reasoning interprets an error or non-success result reported by an observation and identifies a specific cause or the condition that a corrected attempt must satisfy, where the identified cause is tied to the details of the reported failure rather than merely restating the error or generically attributing it to the target functionality.",
    "parameters": [
      {
        "name": "diagnosis_reasoning",
        "type": "reasoning",
        "description": "The reasoning that interprets the failure and identifies its specific cause or required correction."
      },
      {
        "name": "error_observation",
        "type": "observation",
        "description": "The observation reporting the error or non-success result."
      }
    ],
    "assertion_conditions": [
      "The observation reports an error, nonzero exit, or otherwise unsuccessful result from a prior action.",
      "The reasoning identifies a cause, misunderstood condition, or requirement for a corrected attempt.",
      "The identified cause or requirement is consistent with the specific details of the reported error rather than a generic assertion that the target functionality is broken."
    ],
    "exclusion_conditions": [
      "The reasoning merely repeats the error message without interpreting its cause or implications.",
      "The reasoning retries the same operation without identifying any corrective condition.",
      "The reasoning attributes the failure to the target functionality without tying that attribution to the observed error details.",
      "The observation does not report an error or failure."
    ]
  },
  {
    "name": "CORRECTS_FAILED_ACTION_WITH_DIAGNOSED_REVISION",
    "definition": "A subsequent action revises an earlier failed operation in accordance with an explicit diagnosis of the failure, rather than repeating the same operation unchanged.",
    "parameters": [
      {
        "name": "failed_action",
        "type": "action",
        "description": "The earlier action that produced the error result."
      },
      {
        "name": "error_observation",
        "type": "observation",
        "description": "The observation reporting the error from the failed action."
      },
      {
        "name": "correction_reasoning",
        "type": "reasoning",
        "description": "The reasoning that diagnoses the failure and indicates the needed revision."
      },
      {
        "name": "corrective_action",
        "type": "action",
        "description": "The subsequent action that implements the revised approach."
      }
    ],
    "assertion_conditions": [
      "The failed_action is associated with an error_observation reporting failure.",
      "The correction_reasoning identifies a cause or required change in approach.",
      "The corrective_action changes a relevant parameter, command, or method to address the diagnosed failure while pursuing the same goal."
    ],
    "exclusion_conditions": [
      "The subsequent action repeats the failed action identically without revision.",
      "The corrective action is unrelated to the diagnosed failure or targets a different goal.",
      "No error observation or explicit diagnosis supports the revision."
    ]
  },
  {
    "name": "CONCLUDES_TASK_SUCCESS_FROM_ACCUMULATED_EVIDENCE",
    "definition": "The reasoning declares the task successfully completed and supports that declaration by referring to one or more observed verification outcomes rather than only restating the plan or action sequence.",
    "parameters": [
      {
        "name": "conclusion_reasoning",
        "type": "reasoning",
        "description": "The final reasoning that declares completion and cites verification evidence."
      },
      {
        "name": "supporting_observations",
        "type": "observation[]",
        "description": "The observations collectively supplying outcome evidence for the completion claim."
      }
    ],
    "assertion_conditions": [
      "The conclusion_reasoning asserts that the task has been successfully completed.",
      "The reasoning refers to or summarizes at least one observed outcome, such as a produced artifact or confirmed content.",
      "The supporting_observations collectively contain verification evidence rather than only action acknowledgments or plans."
    ],
    "exclusion_conditions": [
      "The reasoning merely restates plans or intermediate actions without asserting completion.",
      "The success assertion is not supported by any observed outcome evidence.",
      "The cited observations are unrelated to the claimed completion."
    ]
  },
  {
    "name": "EVALUATES_ALTERNATIVES",
    "definition": "The reasoning contrasts two or more candidate approaches that could serve the same purpose and settles on one of them on the basis of an explicit comparative rationale.",
    "parameters": [
      {
        "name": "deliberating_reasoning",
        "type": "reasoning",
        "description": "The reasoning that contrasts candidate approaches and justifies the selected one."
      }
    ],
    "assertion_conditions": [
      "The reasoning names at least two candidate approaches, tools, or configuration choices that could serve the same purpose.",
      "The reasoning states a comparative rationale (robustness, availability, compatibility, convenience, simplicity) that favors the selected option over the alternative(s)."
    ],
    "exclusion_conditions": [
      "The reasoning describes only a single approach without contrasting it against another.",
      "The reasoning merely lists planned steps without weighing options against each other.",
      "Another option is mentioned only in passing without any selection between the options being made."
    ]
  },
  {
    "name": "IS_STATE_PROBE",
    "definition": "The action is a read-only inspection of system, environment, or artifact state carried out to obtain information, without altering that state.",
    "parameters": [
      {
        "name": "probe_action",
        "type": "action",
        "description": "The action that inspects rather than modifies system or artifact state."
      }
    ],
    "assertion_conditions": [
      "The action consists of informational query or inspection operations, such as listing directories or processes, reading or dumping configuration, or querying package, user, or service state.",
      "The action's own description or command composition shows an informational purpose and contains no persistent modification of the inspected state."
    ],
    "exclusion_conditions": [
      "The action installs, creates, deletes, or reconfigures resources.",
      "An inspection command appears only incidentally inside an action whose purpose is a persistent change.",
      "The action executes a change and merely reports its own output."
    ]
  },
  {
    "name": "TESTS_ASSUMPTION_WITH_PROBE",
    "definition": "A targeted action is undertaken to discriminate a specific uncertainty or tentative assumption stated in reasoning about the environment, resources, tooling, data, or task requirements, and its observation supplies evidence bearing on that assumption.",
    "parameters": [
      {
        "name": "probe_action",
        "type": "action",
        "description": "The action performing the targeted test or inspection."
      },
      {
        "name": "assumption_reasoning",
        "type": "reasoning",
        "description": "The reasoning stating the uncertainty or tentative assumption being tested."
      },
      {
        "name": "probe_observation",
        "type": "observation",
        "description": "The observation whose content addresses the stated uncertainty."
      }
    ],
    "assertion_conditions": [
      "The reasoning explicitly formulates a specific uncertainty or tentative assumption whose truth would affect the result, procedure, or plan.",
      "The action is chosen so that its result would distinguish between the assumption holding and not holding.",
      "The observation contains content interpretable as evidence for or against the stated assumption."
    ],
    "exclusion_conditions": [
      "No identifiable assumption or uncertainty motivates the inspection.",
      "The action inspects something unrelated to the stated assumption.",
      "The observation does not address the assumption being tested.",
      "The action merely repeats an earlier operation without any assumption being formulated."
    ]
  },
  {
    "name": "GROUNDS_CONCLUSION_IN_OBSERVATION",
    "definition": "The reasoning draws a conclusion, interpretation, or generalized finding about the system, environment, artifacts, or task situation using identifiable content of the observation as supporting evidence.",
    "parameters": [
      {
        "name": "concluding_reasoning",
        "type": "reasoning",
        "description": "The reasoning that states the evidence-based conclusion."
      },
      {
        "name": "evidential_observation",
        "type": "observation",
        "description": "The observation supplying the content that supports the conclusion."
      }
    ],
    "assertion_conditions": [
      "The reasoning states a conclusion, interpretation, or generalized finding that goes beyond merely restating the observation.",
      "Specific content of the observation (reported items, absent items, versions, statuses, listed or fetched output) is identifiable as the basis for that conclusion."
    ],
    "exclusion_conditions": [
      "The reasoning merely restates or paraphrases the observation without drawing an inference from it.",
      "The observation is unrelated to the stated conclusion or provides no identifiable support.",
      "The conclusion is reached solely from prior knowledge or from the task instructions, with the observation contributing no identifiable evidential support."
    ]
  },
  {
    "name": "ADAPTS_PLAN_TO_OBSERVED_STATE",
    "definition": "The reasoning revises the intended course of action in response to a state revealed by the observation that departs from the assumptions of the earlier plan or that constrains the available options.",
    "parameters": [
      {
        "name": "revised_plan_reasoning",
        "type": "reasoning",
        "description": "The reasoning that sets out the adjusted course of action."
      },
      {
        "name": "state_revealing_observation",
        "type": "observation",
        "description": "The observation that reveals the state prompting the adjustment."
      }
    ],
    "assertion_conditions": [
      "The observation reports a state that departs from the assumptions of the earlier course of action or removes options from it.",
      "The reasoning explicitly derives a different set of subsequent steps as a consequence of that observed state."
    ],
    "exclusion_conditions": [
      "The reasoning repeats the previous plan unchanged after the observation.",
      "The reasoning records the observed state as a fact without altering what it intends to do next.",
      "The adjustment is only a reaction to an error from an attempted action that is handled as failure diagnosis and correction."
    ]
  },
  {
    "name": "MITIGATES_ANTICIPATED_FAILURE",
    "definition": "The reasoning anticipates a specific failure mode that could prevent successful completion, and the action implements a measure aimed at preventing or neutralizing that failure before it occurs.",
    "parameters": [
      {
        "name": "safeguard_action",
        "type": "action",
        "description": "The action that implements the preventive measure."
      },
      {
        "name": "risk_reasoning",
        "type": "reasoning",
        "description": "The reasoning that identifies the failure mode and motivates the safeguard."
      }
    ],
    "assertion_conditions": [
      "The reasoning names a concrete failure mode or pitfall that could block the goal or invalidate the result.",
      "The action contains a measure whose stated or evident purpose is to prevent or neutralize that specific failure mode."
    ],
    "exclusion_conditions": [
      "The reasoning names no failure mode, so the measure cannot be tied to a risk.",
      "The action is ordinary setup work with no identifiable correspondence to the described failure mode.",
      "The safeguard is only proposed in reasoning and no corresponding action is performed."
    ]
  },
  {
    "name": "VALIDATES_PRECONDITION_BEFORE_DEPENDENT_ACTION",
    "definition": "The action validates a precondition, configuration, or artifact for correctness and performs a dependent activation or use only after that validation succeeds, within one ordered guarded sequence.",
    "parameters": [
      {
        "name": "guarded_action",
        "type": "action",
        "description": "The action that runs the validation check and the dependent activation or use in a single guarded sequence."
      }
    ],
    "assertion_conditions": [
      "The action invokes a syntax, integrity, or validity check on a precondition, configuration, or artifact that is about to be used or activated.",
      "The dependent activation or use is sequenced after the check and is conditioned on the check succeeding."
    ],
    "exclusion_conditions": [
      "The action performs the dependent activation or use without any preceding validation of the precondition or artifact.",
      "A validation command is run in isolation long after the dependent action has already been performed.",
      "The dependent action proceeds regardless of the validation outcome."
    ]
  },
  {
    "name": "VERIFIES_EXPECTED_OUTCOME",
    "definition": "An action performs an operation or check directed at a specific behavior, output, content, result, resulting state, or constraint that reasoning identified as expected, and the observation reports an outcome consistent with that expectation, thereby confirming it.",
    "parameters": [
      {
        "name": "expectation_reasoning",
        "type": "reasoning",
        "description": "The reasoning stating the expected behavior, output, content, result, state, or constraint."
      },
      {
        "name": "check_action",
        "type": "action",
        "description": "The action executing an operation, inspection, or comparison capable of producing or observing the expected outcome."
      },
      {
        "name": "result_observation",
        "type": "observation",
        "description": "The observation reporting the outcome of the operation, inspection, or comparison."
      }
    ],
    "assertion_conditions": [
      "The reasoning states a specific behavior, output, content, result, state, or constraint that is expected to occur, be present, or be preserved.",
      "The action is directed at exercising, producing, observing, or comparing against that expectation.",
      "The observation reports content consistent with the stated expectation, without contradiction."
    ],
    "exclusion_conditions": [
